(globalThis.CATALOGUE_RECORD_CHUNKS??=Object.create(null))[684]={"source_order":684,"notes":["The superscript letter after '342' is read as 'b', in agreement with the folio label. The trailing dot may be punctuation or a stray mark.","Faint specks scattered across the page were judged to be paper flecks, not pencil writing.","The right edge of the target page meets the gutter at about x≈3130–3170. Writing visible at x>3170 ('f.93', 'e.24…', 'e.24…', 'e.24…', 'e.25…', 'e.25…') belongs to the facing page, fol. 343, as the adjacent overview confirms. It is not transcribed as target content.","The target page is ruled paper with a vertical margin rule at about x≈870. No writing appears in the main column or the margin apart from the folio number.","Image-reviewed finding: the ruled page is blank apart from the folio number '342b' at the top left. I checked the overview and all six native tiles. The main column, the outer margin, the gutter side, and the top and bottom margins contain no writing, pencil notes or marks.","There is a vertical margin rule at about native x≈870. The horizontal rules are printed lines only.","Scattered specks and small strokes, for example near x≈1110, y≈1275 and x≈905, y≈2945, were judged to be paper flecks, not writing.","A small nick on the left paper edge at about y≈1050 and a slight discoloration or crease at the top-left corner are physical features, not text.","The writing at x>3170 ('f.93', 'e.24…', 'e.25…') belongs to the facing page, fol. 343 (source order 685). It is not transcribed here.","The preceding page, fol. 342 (source order 683), ends with 'P.T.O.'. This target verso nevertheless carries no catalogue entries. The entries continue as 'Panjabi contd.' on fol. 343. This is observed context only.","The dot after or beneath the superscript 'b' may be punctuation or a stray mark. The literal_text '342b.' keeps it as a full stop. The source does not settle whether it is intended punctuation."],"records":[{"id":"css-prod-0684-r001","local_id":"r001","source_order":684,"folio":"342b","folio_label":"fol. 342b","sequence":1,"page_id":"957e3e59-0f2f-4990-9e60-16f1e0af64e0","kind":"other","record_type":"non_catalogue_text","source_model_record_type":"non_catalogue_text","subtype":"folio_number","shelfmark":"","titleLiteral":"","titleNormalized":"","displayTitle":"Catalogue text","authorOrSource":"","source":"","subject":"","subjectGroup":"","date":"","extent":"","lines":"","script":"","incipit":"","transcription":"342b.","annotations":["Handwritten folio number in the top-left outer margin, left of the vertical margin rule, at about native x 500–690, y 360–495.","The 'b' is written superscript after '342'. A small dot-like mark sits beneath or after it.","The number is written at a slight upward slant."],"uncertainties":["The superscript letter is read as 'b', consistent with the folio label. Its form could also be taken as a 'b' with a looped stroke.","The trailing dot may be punctuation or a stray mark.","The dot after or beneath the superscript 'b' may be punctuation or a stray mark. The literal_text '342b.' keeps it as a full stop. The source does not settle whether it is intended punctuation."],"focused_readings":[],"reviewNotes":[],"editorialNotes":[],"relationships":[],"editorial_context":[],"block_ids":["b001"],"locations":[{"block_id":"b001","bbox":[495,360,195,135]}],"isCancelled":false,"needsReview":true,"human_verified":false,"verification_status":"machine_reviewed","change_audit":[],"sourceCitationURL":"https://iiif.bodleian.ox.ac.uk/iiif/canvas/957e3e59-0f2f-4990-9e60-16f1e0af64e0.json","auditPath":"audit/pages/0684.json","attachedNotes":[],"resolvedRelationships":[],"attachedRecords":[]}]};
